# shellcheck shell=bash
# Views are written on main only (owner decision, 2026-11-07; conformance/views.toml).
#
#   a pull request that adds or edits a view is refused, path by path; one with
#   only masters passes, and its views are checked compiled fresh;
#   a resolved Warrant's projection is refused in a pull request and never
#   regenerated by the publish step;
#   the publish step stages views only, skips its own commit, reports a missing
#   key without failing, and numbers ids append-only.
#
# Everything happens in a scratch worktree of this repository's HEAD and a bare
# "remote" beside it; this tree is only read. Each claim is paired with a
# refusal, and each refusal is checked for WHICH rule fired.

echo "== views on main (conformance/views.py, views-publish.sh) =="

unset OPENWARRANT_SESSION_ID KATANA_SESSION_ID CODEX_THREAD_ID CODEX_SESSION_ID CLAUDE_CODE_SESSION_ID

vw_ok()   { printf 'ok    %-34s %s\n' "$1" "$2"; PASSED=$((PASSED + 1)); }
vw_fail() { printf 'FAIL  %-34s %s\n' "$1" "$2"; FAILED=$((FAILED + 1)); }
vw_has()  { [[ "$1" == *"$2"* ]]; }

VW_PY="$REPO_ROOT/conformance/views.py"
VW_PUB="$REPO_ROOT/conformance/views-publish.sh"
VW_WAR="$REPO_ROOT/target/debug/war"
VW_TMP=$(mktemp -d)
VW_W="$VW_TMP/w"
VW_R="$VW_TMP/remote.git"
vw_git() { git -C "$VW_W" -c user.email=plant@invalid -c user.name=plant -c commit.gpgsign=false "$@"; }
vw_views() { (cd "$VW_W" && python3 "$VW_PY" "$@" 2>&1); }

git -C "$REPO_ROOT" worktree add -q --detach "$VW_W" HEAD \
    || { printf 'PLANT SETUP FAILED: worktree for views plant\n' >&2; exit 9; }
VW_BASE=$(git -C "$VW_W" rev-parse HEAD)
# The plants job commits fresh views locally first; when it has not, do it here,
# so the base this plant starts from is "main with its views written".
(cd "$VW_W" && python3 "$VW_PY" fresh --war "$VW_WAR" --commit >/dev/null 2>&1) \
    || { printf 'PLANT SETUP FAILED: fresh views in the views plant\n' >&2; exit 9; }
VW_BASE=$(git -C "$VW_W" rev-parse HEAD)

# A resolved Warrant (resolution.toml beside generated/) to test the record rule.
VW_RESOLVED=""
for d in "$VW_W"/docs/warrants/OW-WAR-*/; do
    [[ -f "$d/resolution.toml" && -f "$d/generated/WAR.md" ]] && { VW_RESOLVED=$(basename "$d"); break; }
done
[[ -n "$VW_RESOLVED" ]] || { printf 'PLANT SETUP FAILED: no resolved Warrant with a projection\n' >&2; exit 9; }

# ---- 1. a pull request with only masters passes, and is checked fresh ----
vw_git checkout -q -b vw-masters "$VW_BASE"
(cd "$VW_W" && "$VW_WAR" --root "$VW_W" new "A views plant item" >/dev/null 2>&1) \
    || { printf 'PLANT SETUP FAILED: war new in the views plant\n' >&2; exit 9; }
vw_git add -A -- . ':(exclude)**/generated/**' ':(exclude)docs/generated/**'
vw_git commit -qm "masters only"
VW_MASTERS=$(vw_git rev-parse HEAD)
VW_NEW=$(vw_git diff --name-only "$VW_BASE" HEAD | sed -n 's#^docs/warrants/\([^/]*\)/manifest.toml$#\1#p' | head -1)
out=$(vw_views pr --base "$VW_BASE"); st=$?
if [[ $st -eq 0 ]] && vw_has "$out" "views.pr: pass"; then
    vw_ok "masters-only PR passes" "no view in the change"
else
    vw_fail "masters-only PR passes" "exit $st: $(tr '\n' '|' <<<"$out")"
fi
vw_git checkout -q -f -- . && vw_git clean -fdq
out=$(cd "$VW_W" && TMPDIR="$VW_TMP" python3 "$VW_PY" verify --war "$VW_WAR" 2>&1); st=$?
if [[ $st -eq 0 && -n "$VW_NEW" ]] && vw_has "$out" "differ from the masters' compilation"; then
    vw_ok "masters-only PR checked fresh" "views compiled in a scratch worktree; check --generated passed"
else
    vw_fail "masters-only PR checked fresh" "exit $st (new: ${VW_NEW:-none}): $(tail -3 <<<"$out" | tr '\n' '|')"
fi
# Its committed views are stale (none for the new Warrant), so the committed
# copy would fail where the fresh one passed: proof the check did not read it.
out=$("$VW_WAR" --root "$VW_W" check --generated 2>&1); st=$?
if [[ $st -ne 0 ]] && vw_has "$out" "generated.missing"; then
    vw_ok "stale committed views refused" "generated.missing on the committed copy"
else
    vw_fail "stale committed views refused" "exit $st: the committed copy passed"
fi

# ---- 2. a pull request that adds a view is refused, by path ----
"$VW_WAR" --root "$VW_W" compile >/dev/null 2>&1
vw_git add -A
vw_git commit -qm "with its views"
out=$(vw_views pr --base "$VW_BASE"); st=$?
if [[ $st -eq 1 ]] && vw_has "$out" "views.pr: docs/warrants/$VW_NEW/generated/WAR.json" \
    && vw_has "$out" "views.pr: docs/warrants/generated/CORPUS_STATUS.json"; then
    vw_ok "PR adding a view refused" "views.pr names docs/warrants/$VW_NEW/generated/WAR.json"
else
    vw_fail "PR adding a view refused" "exit $st: $(head -3 <<<"$out" | tr '\n' '|')"
fi
out=$(vw_views drop --base "$VW_BASE"); vw_git commit -qam "drop views" >/dev/null 2>&1
out=$(vw_views pr --base "$VW_BASE"); st=$?
if [[ $st -eq 0 ]]; then
    vw_ok "drop takes the views out" "the same branch passes after views.py drop"
else
    vw_fail "drop takes the views out" "exit $st: $(head -3 <<<"$out" | tr '\n' '|')"
fi

# ---- 3. a hand-edited view is still refused ----
vw_git checkout -q -f -b vw-hand "$VW_BASE"
sed -i '1s/^/hand edit\n/' "$VW_W/docs/generated/CURRENT.md"
vw_git commit -qam "hand-edit a view"
out=$(vw_views pr --base "$VW_BASE"); st=$?
if [[ $st -eq 1 ]] && vw_has "$out" "views.pr: docs/generated/CURRENT.md"; then
    vw_ok "hand-edited view refused" "views.pr: docs/generated/CURRENT.md"
else
    vw_fail "hand-edited view refused" "exit $st: $(head -3 <<<"$out" | tr '\n' '|')"
fi

# ---- 4. a resolved Warrant's projection: refused in a PR ----
vw_git checkout -q -f -b vw-record "$VW_BASE"
printf '\nedited\n' >> "$VW_W/docs/warrants/$VW_RESOLVED/generated/WAR.md"
vw_git commit -qam "edit a resolved projection"
out=$(vw_views pr --base "$VW_BASE"); st=$?
if [[ $st -eq 1 ]] && vw_has "$out" "views.record: docs/warrants/$VW_RESOLVED/generated/WAR.md"; then
    vw_ok "resolved projection refused in PR" "views.record, not views.pr ($VW_RESOLVED)"
else
    vw_fail "resolved projection refused in PR" "exit $st: $(head -3 <<<"$out" | tr '\n' '|')"
fi

# ---- 5. the publish step ----
git clone -q --bare --shared "$REPO_ROOT" "$VW_R" 2>/dev/null \
    || { printf 'PLANT SETUP FAILED: bare remote for the views plant\n' >&2; exit 9; }
vw_publish() { (cd "$VW_W" && VIEWS_REMOTE="$VW_R" VIEWS_BUILD=true WAR="$VW_WAR" VIEWS_ATTEMPTS=1 \
    VIEWS_DEPLOY_KEY="" GITHUB_REPOSITORY="" RUNNER_TEMP="$VW_TMP" bash "$VW_PUB" 2>&1); }
vw_tip() { git -C "$VW_R" rev-parse refs/heads/main; }

# Without a key and without an explicit remote: reported, not failed, not pushed.
out=$(cd "$VW_W" && env -u VIEWS_REMOTE VIEWS_DEPLOY_KEY="" bash "$VW_PUB" 2>&1); st=$?
if [[ $st -eq 0 ]] && vw_has "$out" "views: not published (VIEWS_DEPLOY_KEY not configured)"; then
    vw_ok "no key: reported, not failed" "views: not published (VIEWS_DEPLOY_KEY not configured)"
else
    vw_fail "no key: reported, not failed" "exit $st: $out"
fi

# A master-only main: the publish commits its views, and only views.
vw_git checkout -q -f --detach "$VW_MASTERS"
vw_git push -q -f "$VW_R" HEAD:refs/heads/main
VW_M=$(vw_tip)
out=$(vw_publish); st=$?
VW_P=$(vw_tip)
if [[ $st -eq 0 && "$VW_P" != "$VW_M" ]] && vw_has "$out" "views: published" \
    && [[ "$(git -C "$VW_R" log -1 --format='%ae %s' "$VW_P")" == "views@openwarrant.invalid views: compile main" ]] \
    && git -C "$VW_R" cat-file -e "$VW_P:docs/warrants/$VW_NEW/generated/WAR.json" 2>/dev/null \
    && (cd "$VW_W" && python3 "$VW_PY" only-views --before "$VW_M" --after "$VW_P" >/dev/null 2>&1); then
    vw_ok "publish commits views only" "one fast-forward, fixed identity; $VW_NEW's views included"
else
    vw_fail "publish commits views only" "exit $st: $(tail -3 <<<"$out" | tr '\n' '|')"
fi
out=$(vw_publish); st=$?
if [[ $st -eq 0 && "$(vw_tip)" == "$VW_P" ]] && vw_has "$out" "already a views commit"; then
    vw_ok "publish skips its own commit" "no loop: main's tip is a views commit"
else
    vw_fail "publish skips its own commit" "exit $st: $out"
fi
# Paired refusal: a views-only push is a views push; a master change is not.
if (cd "$VW_W" && ! python3 "$VW_PY" only-views --before "$VW_BASE" --after "$VW_M" >/dev/null 2>&1); then
    vw_ok "a master push is not views-only" "only-views refuses a change with masters in it"
else
    vw_fail "a master push is not views-only" "only-views passed a master change"
fi

# A resolved projection edited on main: the publish refuses to regenerate it.
vw_git checkout -q -f --detach "$VW_P"
printf '\nedited\n' >> "$VW_W/docs/warrants/$VW_RESOLVED/generated/WAR.md"
vw_git commit -qam "a resolved projection, edited"
vw_git push -q -f "$VW_R" HEAD:refs/heads/main
VW_E=$(vw_tip)
out=$(vw_publish); st=$?
if [[ $st -ne 0 && "$(vw_tip)" == "$VW_E" ]] && vw_has "$out" "views.unlisted: docs/warrants/$VW_RESOLVED/generated/WAR.md"; then
    vw_ok "publish never regenerates a record" "views.unlisted; nothing pushed"
else
    vw_fail "publish never regenerates a record" "exit $st: $(tail -3 <<<"$out" | tr '\n' '|')"
fi

# ---- 6. human numbers: append-only, never reused ----
vw_git checkout -q -f --detach "$VW_P"
mkdir -p "$VW_W/docs/work"
printf '# Alpha\n' > "$VW_W/docs/work/alpha.md"
vw_git add docs/work/alpha.md && vw_git commit -qm "alpha"
vw_git push -q -f "$VW_R" HEAD:refs/heads/main
vw_publish >/dev/null
vw_git checkout -q -f --detach "$(vw_tip)"
vw_git rm -q docs/work/alpha.md
printf '# Beta\n' > "$VW_W/docs/work/beta.md"
vw_git add docs/work/beta.md && vw_git commit -qm "beta in, alpha out"
vw_git push -q -f "$VW_R" HEAD:refs/heads/main
out=$(vw_publish); st=$?
idx=$(git -C "$VW_R" show "refs/heads/main:docs/generated/numbers.tsv" 2>/dev/null)
if [[ $st -eq 0 ]] && vw_has "$idx" $'alpha\t1\t' && vw_has "$idx" $'beta\t2\t' \
    && [[ $(wc -l <<<"$idx") -eq 3 ]]; then
    vw_ok "numbers are append-only" "alpha keeps 1 after removal; beta gets 2, not 1"
else
    vw_fail "numbers are append-only" "exit $st: $(tr '\n' '|' <<<"$idx")"
fi
# Paired refusal: an index whose numbers were rewritten is refused.
vw_git checkout -q -f --detach "$(vw_tip)"
printf 'id\tnumber\tfirst_seen\nbeta\t1\tx\nalpha\t2\tx\n' > "$VW_W/docs/generated/numbers.tsv"
out=$(vw_views number --commit x); st=$?
if [[ $st -ne 0 ]] && vw_has "$out" "views.numbers"; then
    vw_ok "renumbered index refused" "views.numbers: not an append to the committed index"
else
    vw_fail "renumbered index refused" "exit $st: $out"
fi
vw_git checkout -q -f -- .

git -C "$REPO_ROOT" worktree remove --force "$VW_W" 2>/dev/null
git -C "$REPO_ROOT" worktree prune 2>/dev/null
for b in vw-masters vw-hand vw-record; do git -C "$REPO_ROOT" branch -q -D "$b" 2>/dev/null; done
[[ "$VW_TMP" == */tmp.* ]] && /usr/bin/rm -rf -- "$VW_TMP"
